import { forwardRef, Children, isValidElement, type ReactNode, useImperativeHandle } from "react";
import { clsx } from "clsx";
import ReactMarkdown from "react-markdown";
import { useTheme } from "@theme";

import { useChatScroll } from "../../hooks/use-chat-scroll";

import { AIMessageProps, AIMarkdownProps, AIMessageListProps } from "./ai-message.types";
import {
  AIMessageClasses,
  StyledAIMessage,
  AIMessageListClasses,
  StyledAIMessageList,
} from "./ai-message.styles";

// --- AIMessage ---

export const AIMessage = forwardRef<HTMLDivElement, AIMessageProps>(
  (
    { className, role = "assistant", children, variant = "default", plainText = false, ...props },
    ref,
  ) => {
    const theme = useTheme();
    const isUser = role === "user";
    const roleClass = isUser ? AIMessageClasses.messageUser : AIMessageClasses.messageAssistant;
    const rootClasses = clsx(AIMessageClasses.root, roleClass, className);

    const processedChildren: ReactNode[] = [];
    let textBuffer: (string | number)[] = [];

    const flushBuffer = () => {
      if (textBuffer.length > 0) {
        const content = textBuffer.join("");
        if (plainText) {
          processedChildren.push(
            <div
              key={`auto-content-${processedChildren.length}`}
              className={AIMessageClasses.plainText}
            >
              {content}
            </div>,
          );
        } else {
          processedChildren.push(
            <AIMarkdown key={`auto-content-${processedChildren.length}`}>{content}</AIMarkdown>,
          );
        }
        textBuffer = [];
      }
    };

    Children.forEach(children, (child) => {
      if (typeof child === "string" || typeof child === "number") {
        textBuffer.push(child);
      } else if (isValidElement(child)) {
        flushBuffer();
        processedChildren.push(child);
      }
    });

    flushBuffer();

    return (
      <StyledAIMessage
        ref={ref}
        className={rootClasses}
        currentTheme={theme}
        plainText={plainText}
        role={role}
        variant={variant}
        {...props}
      >
        {processedChildren}
      </StyledAIMessage>
    );
  },
);

AIMessage.displayName = "AI.Message";

// --- AIMarkdown ---

export const AIMarkdown = forwardRef<HTMLDivElement, AIMarkdownProps>(
  ({ className, children, ...props }, ref) => {
    return (
      <div ref={ref} className={clsx(AIMessageClasses.markdown, className)} {...props}>
        {typeof children === "string" ? <ReactMarkdown>{children}</ReactMarkdown> : children}
      </div>
    );
  },
);

AIMarkdown.displayName = "AI.Markdown";

// --- AIMessageList ---

export const AIMessageList = forwardRef<HTMLDivElement, AIMessageListProps>(
  (
    {
      className,
      children,
      scrollBehavior = "smooth",
      autoScroll = true,
      variant = "default",
      role = "log",
      "aria-live": ariaLive = "polite",
      "aria-atomic": ariaAtomic = false,
      ...props
    },
    forwardedRef,
  ) => {
    const theme = useTheme();
    const rootClasses = clsx(AIMessageListClasses.root, className);

    // Use the smart scroll hook
    const {
      ref: scrollRef,
      onScroll,
      scrollToBottom,
    } = useChatScroll<HTMLDivElement>(children, { enabled: autoScroll });

    // Expose the ref and the scrollToBottom method to the parent
    useImperativeHandle(forwardedRef, () =>
      Object.assign(scrollRef.current!, {
        scrollToBottom,
      }),
    );

    return (
      <StyledAIMessageList
        ref={scrollRef}
        aria-atomic={ariaAtomic}
        aria-live={ariaLive}
        className={rootClasses}
        currentTheme={theme}
        data-scroll-behavior={scrollBehavior}
        role={role}
        tabIndex={0}
        variant={variant}
        onScroll={onScroll}
        {...props}
      >
        {children}
      </StyledAIMessageList>
    );
  },
);

AIMessageList.displayName = "AI.MessageList";
